/**
 * Extension of {@link TestCaseSupplier} that provided multivalue test cases.
 */
public final class MultivalueTestCaseSupplier {

    private static final int MIN_VALUES = 1;
    private static final int MAX_VALUES = 1000;

    private MultivalueTestCaseSupplier() {}

    public static List<TypedDataSupplier> intCases(int min, int max, boolean includeZero) {
        List<TypedDataSupplier> cases = new ArrayList<>();

        for (Block.MvOrdering ordering : Block.MvOrdering.values()) {
            if (0 <= max && 0 >= min && includeZero) {
                cases.add(
                    new TypedDataSupplier(
                        "<0 mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> 0), ordering),
                        DataType.INTEGER
                    )
                );
            }

            if (max != 0) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + max + " mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> max), ordering),
                        DataType.INTEGER
                    )
                );
            }

            if (min != 0 && min != max) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + min + " mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> min), ordering),
                        DataType.INTEGER
                    )
                );
            }

            int lower = Math.max(min, 1);
            int upper = Math.min(max, Integer.MAX_VALUE);
            if (lower < upper) {
                cases.add(
                    new TypedDataSupplier(
                        "<positive mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomIntBetween(lower, upper)), ordering),
                        DataType.INTEGER
                    )
                );
            }

            int lower1 = Math.max(min, Integer.MIN_VALUE);
            int upper1 = Math.min(max, -1);
            if (lower1 < upper1) {
                cases.add(
                    new TypedDataSupplier(
                        "<negative mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomIntBetween(lower1, upper1)), ordering),
                        DataType.INTEGER
                    )
                );
            }

            if (min < 0 && max > 0) {
                cases.add(
                    new TypedDataSupplier("<random mv " + ordering + " ints>", () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> {
                        if (includeZero) {
                            return ESTestCase.randomIntBetween(min, max);
                        }
                        return randomBoolean() ? ESTestCase.randomIntBetween(min, -1) : ESTestCase.randomIntBetween(1, max);
                    }), ordering), DataType.INTEGER)
                );
            }
        }

        return cases;
    }

    public static List<TypedDataSupplier> longCases(long min, long max, boolean includeZero) {
        List<TypedDataSupplier> cases = new ArrayList<>();

        for (Block.MvOrdering ordering : Block.MvOrdering.values()) {
            if (0 <= max && 0 >= min && includeZero) {
                cases.add(
                    new TypedDataSupplier(
                        "<0 mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> 0L), ordering),
                        DataType.LONG
                    )
                );
            }

            if (max != 0) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + max + " mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> max), ordering),
                        DataType.LONG
                    )
                );
            }

            if (min != 0 && min != max) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + min + " mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> min), ordering),
                        DataType.LONG
                    )
                );
            }

            long lower = Math.max(min, 1);
            long upper = Math.min(max, Long.MAX_VALUE);
            if (lower < upper) {
                cases.add(
                    new TypedDataSupplier(
                        "<positive mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomLongBetween(lower, upper)), ordering),
                        DataType.LONG
                    )
                );
            }

            long lower1 = Math.max(min, Long.MIN_VALUE);
            long upper1 = Math.min(max, -1);
            if (lower1 < upper1) {
                cases.add(
                    new TypedDataSupplier(
                        "<negative mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomLongBetween(lower1, upper1)), ordering),
                        DataType.LONG
                    )
                );
            }

            if (min < 0 && max > 0) {
                cases.add(
                    new TypedDataSupplier("<random mv " + ordering + " longs>", () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> {
                        if (includeZero) {
                            return ESTestCase.randomLongBetween(min, max);
                        }
                        return randomBoolean() ? ESTestCase.randomLongBetween(min, -1) : ESTestCase.randomLongBetween(1, max);
                    }), ordering), DataType.LONG)
                );
            }
        }

        return cases;
    }

    public static List<TypedDataSupplier> doubleCases(double min, double max, boolean includeZero) {
        List<TypedDataSupplier> cases = new ArrayList<>();

        for (Block.MvOrdering ordering : Block.MvOrdering.values()) {
            if (0d <= max && 0d >= min && includeZero) {
                cases.add(
                    new TypedDataSupplier(
                        "<0 mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> 0d), ordering),
                        DataType.DOUBLE
                    )
                );
                cases.add(
                    new TypedDataSupplier(
                        "<-0 mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> -0d), ordering),
                        DataType.DOUBLE
                    )
                );
            }

            if (max != 0d) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + max + " mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> max), ordering),
                        DataType.DOUBLE
                    )
                );
            }

            if (min != 0d && min != max) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + min + " mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> min), ordering),
                        DataType.DOUBLE
                    )
                );
            }

            double lower1 = Math.max(min, 0d);
            double upper1 = Math.min(max, 1d);
            if (lower1 < upper1) {
                cases.add(
                    new TypedDataSupplier(
                        "<small positive mv " + ordering + " doubles>",
                        () -> putInOrder(
                            randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomDoubleBetween(lower1, upper1, true)),
                            ordering
                        ),
                        DataType.DOUBLE
                    )
                );
            }

            double lower2 = Math.max(min, -1d);
            double upper2 = Math.min(max, 0d);
            if (lower2 < upper2) {
                cases.add(
                    new TypedDataSupplier(
                        "<small negative mv " + ordering + " doubles>",
                        () -> putInOrder(
                            randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomDoubleBetween(lower2, upper2, true)),
                            ordering
                        ),
                        DataType.DOUBLE
                    )
                );
            }

            double lower3 = Math.max(min, 1d);
            double upper3 = Math.min(max, Double.MAX_VALUE);
            if (lower3 < upper3) {
                cases.add(
                    new TypedDataSupplier(
                        "<big positive mv " + ordering + " doubles>",
                        () -> putInOrder(
                            randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomDoubleBetween(lower3, upper3, true)),
                            ordering
                        ),
                        DataType.DOUBLE
                    )
                );
            }

            double lower4 = Math.max(min, -Double.MAX_VALUE);
            double upper4 = Math.min(max, -1d);
            if (lower4 < upper4) {
                cases.add(
                    new TypedDataSupplier(
                        "<big negative mv " + ordering + " doubles>",
                        () -> putInOrder(
                            randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomDoubleBetween(lower4, upper4, true)),
                            ordering
                        ),
                        DataType.DOUBLE
                    )
                );
            }

            if (min < 0 && max > 0) {
                cases.add(
                    new TypedDataSupplier(
                        "<random mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> {
                            if (includeZero) {
                                return ESTestCase.randomDoubleBetween(min, max, true);
                            }
                            return randomBoolean()
                                ? ESTestCase.randomDoubleBetween(min, -1, true)
                                : ESTestCase.randomDoubleBetween(1, max, true);
                        }), ordering),
                        DataType.DOUBLE
                    )
                );
            }
        }

        return cases;
    }

    private static <T extends Comparable<T>> List<T> putInOrder(List<T> mvData, Block.MvOrdering ordering) {
        switch (ordering) {
            case UNORDERED -> {
            }
            case DEDUPLICATED_UNORDERD -> {
                var dedup = new LinkedHashSet<>(mvData);
                mvData.clear();
                mvData.addAll(dedup);
            }
            case DEDUPLICATED_AND_SORTED_ASCENDING -> {
                var dedup = new HashSet<>(mvData);
                mvData.clear();
                mvData.addAll(dedup);
                Collections.sort(mvData);
            }
            case SORTED_ASCENDING -> {
                Collections.sort(mvData);
            }
            default -> throw new UnsupportedOperationException("unsupported ordering [" + ordering + "]");
        }

        return mvData;
    }
}

public class MvPercentileTests extends AbstractScalarFunctionTestCase {
    public MvPercentileTests(@Name("TestCase") Supplier<TestCaseSupplier.TestCase> testCaseSupplier) {
        this.testCase = testCaseSupplier.get();
    }

    @ParametersFactory
    public static Iterable<Object[]> parameters() {
        List<TestCaseSupplier> cases = new ArrayList<>();

        var fieldSuppliers = Stream.of(
            MultivalueTestCaseSupplier.intCases(Integer.MIN_VALUE, Integer.MAX_VALUE, true),
            MultivalueTestCaseSupplier.longCases(Long.MIN_VALUE, Long.MAX_VALUE, true),
            MultivalueTestCaseSupplier.doubleCases(-Double.MAX_VALUE, Double.MAX_VALUE, true)
        ).flatMap(List::stream).toList();

        var percentileSuppliers = Stream.of(
            TestCaseSupplier.intCases(0, 100, true),
            TestCaseSupplier.longCases(0, 100, true),
            TestCaseSupplier.doubleCases(0, 100, true)
        ).flatMap(List::stream).toList();

        for (var fieldSupplier : fieldSuppliers) {
            for (var percentileSupplier : percentileSuppliers) {
                cases.add(makeSupplier(fieldSupplier, percentileSupplier));
            }
        }

        for (var percentileType : List.of(INTEGER, LONG, DataType.DOUBLE)) {
            cases.addAll(
                List.of(
                    // Doubles
                    new TestCaseSupplier(
                        "median double",
                        List.of(DOUBLE, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10., 5., 10.), DOUBLE, "field"),
                                percentileWithType(50, percentileType)
                            ),
                            evaluatorString(DOUBLE, percentileType),
                            DOUBLE,
                            equalTo(5.)
                        )
                    ),
                    new TestCaseSupplier(
                        "single value double",
                        List.of(DOUBLE, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(55.), DOUBLE, "field"),
                                percentileWithType(randomIntBetween(0, 100), percentileType)
                            ),
                            evaluatorString(DOUBLE, percentileType),
                            DOUBLE,
                            equalTo(55.)
                        )
                    ),
                    new TestCaseSupplier(
                        "p0 double",
                        List.of(DOUBLE, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10., 5., 10.), DOUBLE, "field"),
                                percentileWithType(0, percentileType)
                            ),
                            evaluatorString(DOUBLE, percentileType),
                            DOUBLE,
                            equalTo(-10.)
                        )
                    ),
                    new TestCaseSupplier(
                        "p100 double",
                        List.of(DOUBLE, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10., 5., 10.), DOUBLE, "field"),
                                percentileWithType(100, percentileType)
                            ),
                            evaluatorString(DOUBLE, percentileType),
                            DOUBLE,
                            equalTo(10.)
                        )
                    ),
                    new TestCaseSupplier(
                        "averaged double",
                        List.of(DOUBLE, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10., 5., 10.), DOUBLE, "field"),
                                percentileWithType(75, percentileType)
                            ),
                            evaluatorString(DOUBLE, percentileType),
                            DOUBLE,
                            equalTo(7.5)
                        )
                    ),
                    new TestCaseSupplier(
                        "big double difference",
                        List.of(DOUBLE, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-Double.MAX_VALUE, Double.MAX_VALUE), DOUBLE, "field"),
                                percentileWithType(50, percentileType)
                            ),
                            evaluatorString(DOUBLE, percentileType),
                            DOUBLE,
                            closeTo(0, 0.0000001)
                        )
                    ),

                    // Int
                    new TestCaseSupplier(
                        "median int",
                        List.of(INTEGER, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10, 5, 10), INTEGER, "field"),
                                percentileWithType(50, percentileType)
                            ),
                            evaluatorString(INTEGER, percentileType),
                            INTEGER,
                            equalTo(5)
                        )
                    ),
                    new TestCaseSupplier(
                        "single value int",
                        List.of(INTEGER, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(55), INTEGER, "field"),
                                percentileWithType(randomIntBetween(0, 100), percentileType)
                            ),
                            evaluatorString(INTEGER, percentileType),
                            INTEGER,
                            equalTo(55)
                        )
                    ),
                    new TestCaseSupplier(
                        "p0 int",
                        List.of(INTEGER, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10, 5, 10), INTEGER, "field"),
                                percentileWithType(0, percentileType)
                            ),
                            evaluatorString(INTEGER, percentileType),
                            INTEGER,
                            equalTo(-10)
                        )
                    ),
                    new TestCaseSupplier(
                        "p100 int",
                        List.of(INTEGER, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10, 5, 10), INTEGER, "field"),
                                percentileWithType(100, percentileType)
                            ),
                            evaluatorString(INTEGER, percentileType),
                            INTEGER,
                            equalTo(10)
                        )
                    ),
                    new TestCaseSupplier(
                        "averaged int",
                        List.of(INTEGER, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10, 5, 10), INTEGER, "field"),
                                percentileWithType(75, percentileType)
                            ),
                            evaluatorString(INTEGER, percentileType),
                            INTEGER,
                            equalTo(7)
                        )
                    ),
                    new TestCaseSupplier(
                        "big int difference",
                        List.of(INTEGER, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(Integer.MIN_VALUE, Integer.MAX_VALUE), INTEGER, "field"),
                                percentileWithType(50, percentileType)
                            ),
                            evaluatorString(INTEGER, percentileType),
                            INTEGER,
                            equalTo(-1) // Negative max is 1 smaller than positive max
                        )
                    ),

                    // Long
                    new TestCaseSupplier(
                        "median long",
                        List.of(LONG, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10L, 5L, 10L), LONG, "field"),
                                percentileWithType(50, percentileType)
                            ),
                            evaluatorString(LONG, percentileType),
                            LONG,
                            equalTo(5L)
                        )
                    ),
                    new TestCaseSupplier(
                        "single value long",
                        List.of(LONG, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(55L), LONG, "field"),
                                percentileWithType(randomIntBetween(0, 100), percentileType)
                            ),
                            evaluatorString(LONG, percentileType),
                            LONG,
                            equalTo(55L)
                        )
                    ),
                    new TestCaseSupplier(
                        "p0 long",
                        List.of(LONG, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10L, 5L, 10L), LONG, "field"),
                                percentileWithType(0, percentileType)
                            ),
                            evaluatorString(LONG, percentileType),
                            LONG,
                            equalTo(-10L)
                        )
                    ),
                    new TestCaseSupplier(
                        "p100 long",
                        List.of(LONG, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10L, 5L, 10L), LONG, "field"),
                                percentileWithType(100, percentileType)
                            ),
                            evaluatorString(LONG, percentileType),
                            LONG,
                            equalTo(10L)
                        )
                    ),
                    new TestCaseSupplier(
                        "averaged long",
                        List.of(LONG, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(-10L, 5L, 10L), LONG, "field"),
                                percentileWithType(75, percentileType)
                            ),
                            evaluatorString(LONG, percentileType),
                            LONG,
                            equalTo(7L)
                        )
                    ),
                    new TestCaseSupplier(
                        "big long difference",
                        List.of(LONG, percentileType),
                        () -> new TestCaseSupplier.TestCase(
                            List.of(
                                new TestCaseSupplier.TypedData(List.of(Long.MIN_VALUE, Long.MAX_VALUE), LONG, "field"),
                                percentileWithType(50, percentileType)
                            ),
                            evaluatorString(LONG, percentileType),
                            LONG,
                            equalTo(0L)
                        )
                    )
                )
            );
        }

        return parameterSuppliersFromTypedDataWithDefaultChecks(
            (nullPosition, nullValueDataType, original) -> nullValueDataType == DataType.NULL && nullPosition == 0
                ? DataType.NULL
                : original.expectedType(),
            (nullPosition, nullData, original) -> original,
            cases,
            (v, p) -> "numeric except unsigned_long"
        );
    }

    @SuppressWarnings("unchecked")
    private static TestCaseSupplier makeSupplier(
        TestCaseSupplier.TypedDataSupplier fieldSupplier,
        TestCaseSupplier.TypedDataSupplier percentileSupplier
    ) {
        return new TestCaseSupplier(
            "field: " + fieldSupplier.name() + ", percentile: " + percentileSupplier.name(),
            List.of(fieldSupplier.type(), percentileSupplier.type()),
            () -> {
                var fieldTypedData = fieldSupplier.get();
                var percentileTypedData = percentileSupplier.get();

                var values = (List<Number>) fieldTypedData.data();
                var percentile = ((Number) percentileTypedData.data()).doubleValue();

                var expected = calculatePercentile(values, percentile);

                return new TestCaseSupplier.TestCase(
                    List.of(fieldTypedData, percentileTypedData),
                    evaluatorString(fieldSupplier.type(), percentileSupplier.type()),
                    fieldSupplier.type(),
                    expected instanceof Double expectedDouble
                        ? closeTo(expectedDouble, Math.abs(expectedDouble * 0.0000001))
                        : equalTo(expected)
                );
            }
        );
    }

    private static Number calculatePercentile(List<Number> rawValues, double percentile) {
        if (rawValues.isEmpty() || percentile < 0 || percentile > 100) {
            return null;
        }

        if (rawValues.size() == 1) {
            return rawValues.get(0);
        }

        int valueCount = rawValues.size();
        var p = percentile / 100.0;
        var index = p * (valueCount - 1);
        var lowerIndex = (int) index;
        var upperIndex = lowerIndex + 1;
        var fraction = index - lowerIndex;

        if (rawValues.get(0) instanceof Integer) {
            var values = rawValues.stream().mapToInt(Number::intValue).sorted().toArray();

            if (percentile == 0) {
                return values[0];
            } else if (percentile == 100) {
                return values[valueCount - 1];
            } else {
                assert lowerIndex >= 0 && upperIndex < valueCount;
                var difference = (long) values[upperIndex] - values[lowerIndex];
                return values[lowerIndex] + (int) (fraction * difference);
            }
        }

        if (rawValues.get(0) instanceof Long) {
            var values = rawValues.stream().mapToLong(Number::longValue).sorted().toArray();

            if (percentile == 0) {
                return values[0];
            } else if (percentile == 100) {
                return values[valueCount - 1];
            } else {
                assert lowerIndex >= 0 && upperIndex < valueCount;
                return calculatePercentile(fraction, new BigDecimal(values[lowerIndex]), new BigDecimal(values[upperIndex])).longValue();
            }
        }

        if (rawValues.get(0) instanceof Double) {
            var values = rawValues.stream().mapToDouble(Number::doubleValue).sorted().toArray();

            if (percentile == 0) {
                return values[0];
            } else if (percentile == 100) {
                return values[valueCount - 1];
            } else {
                assert lowerIndex >= 0 && upperIndex < valueCount;
                return calculatePercentile(fraction, new BigDecimal(values[lowerIndex]), new BigDecimal(values[upperIndex])).doubleValue();
            }
        }

        throw new IllegalArgumentException("Unsupported type: " + rawValues.get(0).getClass());
    }

    private static BigDecimal calculatePercentile(double fraction, BigDecimal lowerValue, BigDecimal upperValue) {
        return lowerValue.add(new BigDecimal(fraction).multiply(upperValue.subtract(lowerValue)));
    }

    private static TestCaseSupplier.TypedData percentileWithType(int value, DataType type) {
        return new TestCaseSupplier.TypedData(switch (type) {
            case INTEGER -> value;
            case LONG -> (long) value;
            default -> (double) value;
        }, type, "percentile");
    }

    private static String evaluatorString(DataType fieldDataType, DataType percentileDataType) {
        var fieldTypeName = StringUtils.underscoreToLowerCamelCase(fieldDataType.name());
        var percentileTypeName = StringUtils.underscoreToLowerCamelCase(percentileDataType.name());

        fieldTypeName = fieldTypeName.substring(0, 1).toUpperCase() + fieldTypeName.substring(1);
        percentileTypeName = percentileTypeName.substring(0, 1).toUpperCase() + percentileTypeName.substring(1);

        return "MvPercentile"
            + fieldTypeName
            + percentileTypeName
            + "Evaluator[values=Attribute[channel=0], percentile=Attribute[channel=1]]";
    }

    @Override
    protected final Expression build(Source source, List<Expression> args) {
        return new MvPercentile(source, args.get(0), args.get(1));
    }
}

/**
 * Extension of {@link TestCaseSupplier} that provided multivalue test cases.
 */
public final class MultivalueTestCaseSupplier {

    private static final int MIN_VALUES = 1;
    private static final int MAX_VALUES = 1000;

    private MultivalueTestCaseSupplier() {}

    public static List<TypedDataSupplier> intCases(int min, int max, boolean includeZero) {
        List<TypedDataSupplier> cases = new ArrayList<>();

        for (Block.MvOrdering ordering : Block.MvOrdering.values()) {
            if (0 <= max && 0 >= min && includeZero) {
                cases.add(
                    new TypedDataSupplier(
                        "<0 mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> 0), ordering),
                        DataType.INTEGER
                    )
                );
            }

            if (max != 0) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + max + " mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> max), ordering),
                        DataType.INTEGER
                    )
                );
            }

            if (min != 0 && min != max) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + min + " mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> min), ordering),
                        DataType.INTEGER
                    )
                );
            }

            int lower = Math.max(min, 1);
            int upper = Math.min(max, Integer.MAX_VALUE);
            if (lower < upper) {
                cases.add(
                    new TypedDataSupplier(
                        "<positive mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomIntBetween(lower, upper)), ordering),
                        DataType.INTEGER
                    )
                );
            }

            int lower1 = Math.max(min, Integer.MIN_VALUE);
            int upper1 = Math.min(max, -1);
            if (lower1 < upper1) {
                cases.add(
                    new TypedDataSupplier(
                        "<negative mv " + ordering + " ints>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomIntBetween(lower1, upper1)), ordering),
                        DataType.INTEGER
                    )
                );
            }

            if (min < 0 && max > 0) {
                cases.add(
                    new TypedDataSupplier("<random mv " + ordering + " ints>", () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> {
                        if (includeZero) {
                            return ESTestCase.randomIntBetween(min, max);
                        }
                        return randomBoolean() ? ESTestCase.randomIntBetween(min, -1) : ESTestCase.randomIntBetween(1, max);
                    }), ordering), DataType.INTEGER)
                );
            }
        }

        return cases;
    }

    public static List<TypedDataSupplier> longCases(long min, long max, boolean includeZero) {
        List<TypedDataSupplier> cases = new ArrayList<>();

        for (Block.MvOrdering ordering : Block.MvOrdering.values()) {
            if (0 <= max && 0 >= min && includeZero) {
                cases.add(
                    new TypedDataSupplier(
                        "<0 mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> 0L), ordering),
                        DataType.LONG
                    )
                );
            }

            if (max != 0) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + max + " mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> max), ordering),
                        DataType.LONG
                    )
                );
            }

            if (min != 0 && min != max) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + min + " mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> min), ordering),
                        DataType.LONG
                    )
                );
            }

            long lower = Math.max(min, 1);
            long upper = Math.min(max, Long.MAX_VALUE);
            if (lower < upper) {
                cases.add(
                    new TypedDataSupplier(
                        "<positive mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomLongBetween(lower, upper)), ordering),
                        DataType.LONG
                    )
                );
            }

            long lower1 = Math.max(min, Long.MIN_VALUE);
            long upper1 = Math.min(max, -1);
            if (lower1 < upper1) {
                cases.add(
                    new TypedDataSupplier(
                        "<negative mv " + ordering + " longs>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomLongBetween(lower1, upper1)), ordering),
                        DataType.LONG
                    )
                );
            }

            if (min < 0 && max > 0) {
                cases.add(
                    new TypedDataSupplier("<random mv " + ordering + " longs>", () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> {
                        if (includeZero) {
                            return ESTestCase.randomLongBetween(min, max);
                        }
                        return randomBoolean() ? ESTestCase.randomLongBetween(min, -1) : ESTestCase.randomLongBetween(1, max);
                    }), ordering), DataType.LONG)
                );
            }
        }

        return cases;
    }

    public static List<TypedDataSupplier> doubleCases(double min, double max, boolean includeZero) {
        List<TypedDataSupplier> cases = new ArrayList<>();

        for (Block.MvOrdering ordering : Block.MvOrdering.values()) {
            if (0d <= max && 0d >= min && includeZero) {
                cases.add(
                    new TypedDataSupplier(
                        "<0 mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> 0d), ordering),
                        DataType.DOUBLE
                    )
                );
                cases.add(
                    new TypedDataSupplier(
                        "<-0 mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> -0d), ordering),
                        DataType.DOUBLE
                    )
                );
            }

            if (max != 0d) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + max + " mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> max), ordering),
                        DataType.DOUBLE
                    )
                );
            }

            if (min != 0d && min != max) {
                cases.add(
                    new TypedDataSupplier(
                        "<" + min + " mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> min), ordering),
                        DataType.DOUBLE
                    )
                );
            }

            double lower1 = Math.max(min, 0d);
            double upper1 = Math.min(max, 1d);
            if (lower1 < upper1) {
                cases.add(
                    new TypedDataSupplier(
                        "<small positive mv " + ordering + " doubles>",
                        () -> putInOrder(
                            randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomDoubleBetween(lower1, upper1, true)),
                            ordering
                        ),
                        DataType.DOUBLE
                    )
                );
            }

            double lower2 = Math.max(min, -1d);
            double upper2 = Math.min(max, 0d);
            if (lower2 < upper2) {
                cases.add(
                    new TypedDataSupplier(
                        "<small negative mv " + ordering + " doubles>",
                        () -> putInOrder(
                            randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomDoubleBetween(lower2, upper2, true)),
                            ordering
                        ),
                        DataType.DOUBLE
                    )
                );
            }

            double lower3 = Math.max(min, 1d);
            double upper3 = Math.min(max, Double.MAX_VALUE);
            if (lower3 < upper3) {
                cases.add(
                    new TypedDataSupplier(
                        "<big positive mv " + ordering + " doubles>",
                        () -> putInOrder(
                            randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomDoubleBetween(lower3, upper3, true)),
                            ordering
                        ),
                        DataType.DOUBLE
                    )
                );
            }

            double lower4 = Math.max(min, -Double.MAX_VALUE);
            double upper4 = Math.min(max, -1d);
            if (lower4 < upper4) {
                cases.add(
                    new TypedDataSupplier(
                        "<big negative mv " + ordering + " doubles>",
                        () -> putInOrder(
                            randomList(MIN_VALUES, MAX_VALUES, () -> ESTestCase.randomDoubleBetween(lower4, upper4, true)),
                            ordering
                        ),
                        DataType.DOUBLE
                    )
                );
            }

            if (min < 0 && max > 0) {
                cases.add(
                    new TypedDataSupplier(
                        "<random mv " + ordering + " doubles>",
                        () -> putInOrder(randomList(MIN_VALUES, MAX_VALUES, () -> {
                            if (includeZero) {
                                return ESTestCase.randomDoubleBetween(min, max, true);
                            }
                            return randomBoolean()
                                ? ESTestCase.randomDoubleBetween(min, -1, true)
                                : ESTestCase.randomDoubleBetween(1, max, true);
                        }), ordering),
                        DataType.DOUBLE
                    )
                );
            }
        }

        return cases;
    }

    private static <T extends Comparable<T>> List<T> putInOrder(List<T> mvData, Block.MvOrdering ordering) {
        switch (ordering) {
            case UNORDERED -> {
            }
            case DEDUPLICATED_UNORDERD -> {
                var dedup = new LinkedHashSet<>(mvData);
                mvData.clear();
                mvData.addAll(dedup);
            }
            case DEDUPLICATED_AND_SORTED_ASCENDING -> {
                var dedup = new HashSet<>(mvData);
                mvData.clear();
                mvData.addAll(dedup);
                Collections.sort(mvData);
            }
            case SORTED_ASCENDING -> {
                Collections.sort(mvData);
            }
            default -> throw new UnsupportedOperationException("unsupported ordering [" + ordering + "]");
        }

        return mvData;
    }
}

